sys_script_client.script:
function onLoad() {
    if (g_form.getValue('form_type') == '1' || g_form.getValue('state') != '1') {
        return;
    }
    g_form.clearOptions('product_team');
    g_form.addOption('product_team', '', '-- None --');
    var userGroups = [];
    var ga = new GlideAjax('x_hsb11_mss_oper_0.MSS_Operation_Request_Utils');
    ga.addParam('sysparm_name', 'getPRMProductUserGroups'); // Call the getUserGroups method
    ga.getXMLAnswer(function(response) {
        if (response) {
            userGroups = JSON.parse(response); // Parse the JSON response
            filterProductTeamChoices(userGroups); // Compare and filter choices for the product_team field
        }
    });

    function filterProductTeamChoices(groups) {
        for (var value in groups) {
            if (groups.hasOwnProperty(value)) {
                g_form.addOption('product_team', value, groups[value]);

            }
        }

    }

    g_form.setValue('assignment_group', '8eb777371b5a6a542ac120a8b04bcb7e'); //iQube-PRM-Req-Apprvr

    //Remove receving side other product team
    g_form.removeOption('receiving_product_team', "OthersNoneOfAbove");
	g_form.removeOption('receiving_product_team', "OthersNOTForClientDataServices");
}
